using System.ComponentModel.DataAnnotations;
using Orders.Domain;

namespace Orders.Models;

public class PlaceOrderRequest
{
    // Generated by the shop at checkout, so a repeated request returns the same order.
    [Required] public Guid? Id { get; set; }
    [Required, MinLength(1, ErrorMessage = "Your cart is empty.")] public List<OrderItemRequest> Items { get; set; } = [];
    [Required] public DeliveryAddressRequest? DeliveryAddress { get; set; }
    [Required] public PaymentCardRequest? PaymentCard { get; set; }
}

public class OrderItemRequest
{
    [Required, MaxLength(50)] public string Sku { get; set; } = "";
    [Range(1, 99)] public int Quantity { get; set; }
}

// The address and card the customer picked, as the shop loaded them from Profile.
public class DeliveryAddressRequest
{
    [Required, MaxLength(200)] public string RecipientName { get; set; } = "";
    [Required, MaxLength(200)] public string Line1 { get; set; } = "";
    [MaxLength(200)] public string? Line2 { get; set; }
    [Required, MaxLength(100)] public string Suburb { get; set; } = "";
    [Required, MaxLength(50)] public string State { get; set; } = "";
    [Required, MaxLength(10)] public string Postcode { get; set; } = "";
    [Required, MaxLength(100)] public string Country { get; set; } = "";
    [MaxLength(30)] public string? Phone { get; set; }

    public OrderAddress ToAddress() => new()
    {
        RecipientName = RecipientName,
        Line1 = Line1,
        Line2 = Line2,
        Suburb = Suburb,
        State = State,
        Postcode = Postcode,
        Country = Country,
        Phone = Phone,
    };
}

public class PaymentCardRequest
{
    [Range(1, int.MaxValue)] public int Id { get; set; }
    [Required, MaxLength(20)] public string Brand { get; set; } = "";
    [Required, RegularExpression(@"^\d{4}$")] public string Last4 { get; set; } = "";
}

public record OrderSummaryResponse(Guid Id, string Status, int ItemCount, decimal Total, string Currency, DateTime PlacedAt)
{
    public static OrderSummaryResponse From(Order o) =>
        new(o.Id, o.Status.ToString(), o.Lines.Sum(l => l.Quantity), o.Total, o.Currency, o.PlacedAt);
}

public record OrderResponse(
    Guid Id, string Status,
    IReadOnlyList<OrderLineResponse> Lines,
    OrderAddressResponse DeliveryAddress,
    OrderCardResponse PaymentCard,
    decimal Subtotal, decimal Shipping, decimal Total, string Currency,
    DateTime PlacedAt)
{
    public static OrderResponse From(Order o) => new(
        o.Id, o.Status.ToString(),
        o.Lines.OrderBy(l => l.Id).Select(l => new OrderLineResponse(l.Sku, l.Name, l.UnitPrice, l.Quantity, l.LineTotal)).ToList(),
        new OrderAddressResponse(
            o.DeliveryAddress.RecipientName, o.DeliveryAddress.Line1, o.DeliveryAddress.Line2, o.DeliveryAddress.Suburb,
            o.DeliveryAddress.State, o.DeliveryAddress.Postcode, o.DeliveryAddress.Country, o.DeliveryAddress.Phone),
        new OrderCardResponse(o.CardBrand, o.CardLast4),
        o.Subtotal, o.Shipping, o.Total, o.Currency, o.PlacedAt);
}

public record OrderLineResponse(string Sku, string Name, decimal UnitPrice, int Quantity, decimal LineTotal);

public record OrderAddressResponse(
    string RecipientName, string Line1, string? Line2, string Suburb,
    string State, string Postcode, string Country, string? Phone);

public record OrderCardResponse(string Brand, string Last4);
